theme.globalCss:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400&family=Inter:wght@300;400;500;600&family=Rye&display=swap');

.volturianoStamp {
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0.5;
  transition: opacity 0.3s ease;
  text-decoration: none;
}

.volturianoStamp:hover {
  opacity: 1;
}

.stampContent {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.stampText {
  font-family: 'Inter', sans-serif;
  font-size: 8px;
  letter-spacing: 0.2em;
  color: #a8a29e;
  font-weight: 500;
}

.stampSeparator {
  height: 1px;
  width: 20px;
  background-color: #a8a29e;
}

.stampLogo {
  height: 16px;
  width: auto;
  filter: grayscale(100%) invert(1);
}
